window.__texto({"id": "726175367", "paragrafos": [{"c": "identifica", "t": "PORTARIA SDA/MAPA Nº 1.673, DE 17 DE AGOSTO DE 2026"}, {"c": "ementa", "t": "Submete à Consulta Pública, pelo prazo de 45 (quarenta e cinco) dias, a Minuta de Portaria que Estabelece os procedimentos de controle para a importação e a exportação de insumos agrícolas."}, {"c": "dou-paragraph", "t": "O SECRETÁRIO DE DEFESA AGROPECUÁRIA, DO MINISTÉRIO DA AGRICULTURA E PECUÁRIA, no uso das atribuições que lhe conferem os arts. 23 e 48 do Anexo I ao Decreto nº 12.642, de 1º de outubro de 2025, e tendo em vista o disposto no Decreto nº 24.114, de 12 de abril de 1934, no Decreto nº 5.759, de 17 de abril de 2006, no Decreto nº 5.741, de 30 de março de 2006, na Instrução Normativa nº 38, de 1º de outubro de 2018, e o que consta do Processo nº 21000.041787/2026-87, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica submetida à Consulta Pública, pelo prazo de 45 (quarenta e cinco) dias, a Minuta de Portaria que estabelece os procedimentos de controle para a importação e a exportação de insumos agrícolas."}, {"c": "dou-paragraph", "t": "Parágrafo único. A Minuta de Portaria encontra-se disponível na plataforma eletrônica do Governo Federal: https://www.gov.br/agricultura/pt-br/acesso-a-informacao/participacao-social/consultas-publicas."}, {"c": "dou-paragraph", "t": "Art. 2º As sugestões, tecnicamente fundamentadas, deverão ser encaminhadas via Sistema de Monitoramento de Atos Normativos - SISMAN, da Secretaria de Defesa Agropecuária - SDA/MAPA, por meio do link: https://sistemasweb.agricultura.gov.br/pages/SISMAN.html"}, {"c": "dou-paragraph", "t": "§1º Para ter acesso ao Sistema de Monitoramento de Atos Normativos - SISMAN, o usuário deverá efetuar cadastro prévio no Sistema de Solicitação de Acesso - SOLICITA, do MAPA, por meio do link: https://sistemasweb.agricultura.gov.br/solicita/"}, {"c": "dou-paragraph", "t": "§2º Os critérios para aceitação das sugestões de alteração, inclusão ou exclusão nos textos levarão em conta a obediência aos demais ditames legais, a relevância e o impacto positivo da contribuição para a efetividade do sistema de importação e a exportação de insumos agrícolas."}, {"c": "dou-paragraph", "t": "Art. 3º A inobservância ao art. 2º, desta Portaria, implicará na recusa automática da sugestão ou comentário encaminhado."}, {"c": "dou-paragraph", "t": "Art. 4º Findo o prazo estabelecido no art. 1º, desta Portaria, o Departamento de Sanidade Vegetal e Insumos Agrícolas deverá avaliar, em articulação com as áreas técnicas envolvidas com o tema objeto desta Portaria, as sugestões recebidas e proceder às adequações pertinentes."}, {"c": "dou-paragraph", "t": "Art. 5º Esta Portaria entra em vigor na data da sua publicação."}, {"c": "assina", "t": "CARLOS GOULART"}, {"c": "anexo", "t": "ANEXOPortaria SDA/MAPA nº 00, de 13 de AGOSTO de 2026"}, {"c": "dou-paragraph", "t": "O MINISTRO DE ESTADO DA AGRICULTURA E PECUÁRIA, no uso da atribuição que lhe confere o art. 87, parágrafo único, inciso II, da Constituição, tendo em vista o disposto na Lei nº 6.984, de 16 de dezembro de 1980, na Lei nº 10.711, de 5 de agosto de 2003, na Lei nº 14.785, de 27 de dezembro de 2023, e o que consta do Processo nº 21000.041787/2026-87, resolve:"}, {"c": "dou-paragraph", "t": "CAPÍTULO I"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES GERAIS"}, {"c": "dou-paragraph", "t": "Art. 1º Estabelecer os procedimentos de controle para a importação e a exportação de insumos agrícolas, compreendendo:"}, {"c": "dou-paragraph", "t": "I - produtos técnicos, pré-misturas, agrotóxicos formulados e afins;"}, {"c": "dou-paragraph", "t": "II - fertilizantes e correlatos; e"}, {"c": "dou-paragraph", "t": "III - sementes, mudas e material de propagação vegetativa."}, {"c": "dou-paragraph", "t": "Art. 2º Esta norma se aplica à importação e à exportação de insumos agrícolas por qualquer meio ou forma de transporte, incluindo os transportados como remessa internacional ou como bagagem de viajantes."}, {"c": "dou-paragraph", "t": "Art. 3º A importação e a exportação de que tratam esta norma observarão o disposto na legislação correlata, inclusive a fitossanitária, e os procedimentos para registro no Portal Único de Comércio Exterior ou seu equivalente, e sistemas complementares."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Da importação"}, {"c": "dou-paragraph", "t": "Art. 4º Os insumos agrícolas importados estão sujeitos aos seguintes procedimentos de controle:"}, {"c": "dou-paragraph", "t": "I - dispensa de autorização para importação e sujeição aos procedimentos de controle no momento da importação;"}, {"c": "dou-paragraph", "t": "II - sujeição a autorização para importação, válida para múltiplas operações, e aos procedimentos de controle no momento da importação; ou"}, {"c": "dou-paragraph", "t": "III - sujeição a autorização para importação, válida para uma única operação, e aos procedimentos de controle no momento da importação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O procedimento de controle aplicável a cada tipo de insumo agrícola está estabelecido nos Capítulos II, III e IV."}, {"c": "dou-paragraph", "t": "Art. 5º Quando exigida, a autorização para importação deverá ser solicitada pelo módulo de Licenças, Permissões, Certificados e Outros Documentos - LPCO, ou seu equivalente, do Portal Único de Comércio Exterior."}, {"c": "dou-paragraph", "t": "Art. 6º O LPCO de autorização para importação deverá ser registrado conforme modelo específico para o tipo de insumo agrícola que se pretende importar, fornecendo as informações e anexando os documentos exigidos nos Capítulos II, III e IV, conforme o caso."}, {"c": "dou-paragraph", "t": "§ 1º O LPCO será analisado por Auditor Fiscal Federal Agropecuário no prazo de dez dias úteis."}, {"c": "dou-paragraph", "t": "§ 2º Quando constatada pendência, a exigência será registrada no LPCO e deverá ser atendida pelo importador no prazo de cinco dias úteis."}, {"c": "dou-paragraph", "t": "§ 3º Após o atendimento da exigência, o LPCO será reanalisado no prazo de cinco dias úteis."}, {"c": "dou-paragraph", "t": "§ 4º Satisfeitas as exigências legais, o LPCO será deferido."}, {"c": "dou-paragraph", "t": "§ 5º O LPCO será indeferido quando:"}, {"c": "dou-paragraph", "t": "I - constatada irregularidade insanável; ou"}, {"c": "dou-paragraph", "t": "II - não atendidas as exigências no prazo estabelecido."}, {"c": "dou-paragraph", "t": "Art. 7º A autorização para importação poderá ser concedida para uma única operação ou para múltiplas operações, ambas realizadas dentro do prazo de vigência da autorização e no limite da quantidade autorizada, conforme definido nos Capítulos II, III e IV."}, {"c": "dou-paragraph", "t": "Art. 8º O importador poderá solicitar retificação ou prorrogação da autorização para importação, mediante funcionalidade específica do LPCO."}, {"c": "dou-paragraph", "t": "Parágrafo único. A solicitação de retificação ou de prorrogação será processada nas mesmas condições e prazos previstos no art. 6º."}, {"c": "dou-paragraph", "t": "Art. 9º A autorização para importação poderá ser revogada a qualquer tempo, sem prévia comunicação ao importador, quando:"}, {"c": "dou-paragraph", "t": "I - o produto passar a ter sua importação proibida pelo Brasil;"}, {"c": "dou-paragraph", "t": "II - a origem do produto tiver alteração em sua situação fitossanitária, considerada de risco para o Brasil;"}, {"c": "dou-paragraph", "t": "III - o importador estiver submetido a medida cautelar de suspensão temporária de atividade, de etapa ou de processo de fabricação de produto; ou"}, {"c": "dou-paragraph", "t": "IV - o importador ou o produto tiver sua situação de registro ou cadastro junto ao Ministério da Agricultura e Pecuária suspensa, cassada ou cancelada, mediante decisão em processo administrativo, ou vencida pelo término de validade do registro ou cadastro."}, {"c": "dou-paragraph", "t": "Art. 10. O controle agropecuário no momento da importação dar-se-á por meio do módulo Declaração Única de Importação - Duimp, ou seu equivalente, no Portal Único de Comércio Exterior."}, {"c": "dou-paragraph", "t": "Art. 11. Em caso de proibição de ingresso do insumo agrícola, o importador arcará com as medidas previstas na legislação."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Da exportação"}, {"c": "dou-paragraph", "t": "Art. 12. A exportação de insumos agrícolas deverá atender ao disposto nos Capítulos II, III e IV."}, {"c": "dou-paragraph", "t": "Art. 13. Quando exigido, o controle agropecuário no momento da exportação, para fins de emissão de Certificado Fitossanitário ou de Certificado Fitossanitário de Reexportação ou para atendimento de exigências do país importador, deverá ser solicitado pelo módulo LPCO, ou seu equivalente, do Portal Único de Comércio Exterior."}, {"c": "dou-paragraph", "t": "Art. 14. A exportação de insumos agrícolas deverá atender, além da legislação brasileira, às exigências de acordos e tratados que regem o comércio internacional e aquelas estabelecidas pelo país importador."}, {"c": "dou-paragraph", "t": "CAPÍTULO II"}, {"c": "dou-paragraph", "t": "DA IMPORTAÇÃO E DA EXPORTAÇÃO DE PRODUTOS TÉCNICOS, PRÉ-MISTURAS, AGROTÓXICOS FORMULADOS E AFINS"}, {"c": "dou-paragraph", "t": "Art. 15. As atividades de importação e exportação dos produtos técnicos, pré-misturas, agrotóxicos formulados e afins, somente poderão ser exercidas por pessoa jurídica devidamente constituída, pública ou privada e estar devidamente registrada no Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 16. A importação e exportação dos produtos previstos no artigo 1º somente será permitida quando os produtos estiverem registrados ou autorizados pelo Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Da autorização para importação de produtos técnicos, pré-misturas, agrotóxicos formulados e afins"}, {"c": "dou-paragraph", "t": "Art. 17. Somente poderão importar produtos técnicos, pré-misturas, agrotóxicos formulados e afins, as empresas titulares de registro de produto ou suas filiais e, no caso de terceiros, quando autorizados por meio de ato publicado pelo Ministério da Agricultura e Pecuária no Diário Oficial da União ou em sítio eletrônico, que o torne público."}, {"c": "dou-paragraph", "t": "Art. 18. Padrões analíticos, matérias-primas, ingredientes inertes e aditivos, considerados componentes de agrotóxicos e afins; além dos adjuvantes, à exceção dos produtos técnicos e ingredientes ativos, não deverão ser registrados no Portal Único de Comércio Exterior sob a anuência do Ministério da Agricultura e Pecuária e poderão receber o tratamento administrativo de monitoramento como medida imposta pela fiscalização agropecuária."}, {"c": "dou-paragraph", "t": "Art. 19. A importação dos produtos técnicos, pré-misturas, agrotóxicos formulados e afins será submetida ao gerenciamento/gestão de risco agropecuário e à seleção para um dos seguintes canais de fiscalização:"}, {"c": "dou-paragraph", "t": "I - simplificado (Verde): Dispensado da análise documental, vistoria, conferência e inspeção da mercadoria;"}, {"c": "dou-paragraph", "t": "II - intermediário (Amarelo): Análise documental obrigatória e, nos casos em que não for constatada qualquer não conformidade, dispensada da vistoria, conferência e inspeção da mercadoria; ou"}, {"c": "dou-paragraph", "t": "III - completo (Vermelho): Análise documental, vistoria, conferência e inspeção da mercadoria."}, {"c": "dou-paragraph", "t": "Parágrafo único. Mesmo em declarações de importação selecionadas em canal amarelo, havendo indícios de irregularidade o Auditor Fiscal Federal Agropecuário responsável pelo processo de importação poderá solicitar a realização de inspeção da mercadoria."}, {"c": "dou-paragraph", "t": "Art. 20. São critérios a serem avaliados no gerenciamento/gestão de risco agropecuário para agrotóxicos formulados, produtos técnicos, pré-misturas, matérias-primas e afins:"}, {"c": "dou-paragraph", "t": "I - origem;"}, {"c": "dou-paragraph", "t": "II - procedência;"}, {"c": "dou-paragraph", "t": "III - destino;"}, {"c": "dou-paragraph", "t": "IV - atividade do operador de comércio ou trânsito internacional;"}, {"c": "dou-paragraph", "t": "V - histórico de conformidade e regularidade;"}, {"c": "dou-paragraph", "t": "VI - Natureza e quantidade da mercadoria;"}, {"c": "dou-paragraph", "t": "VII - tipo de operação;"}, {"c": "dou-paragraph", "t": "VIII - uso proposto;"}, {"c": "dou-paragraph", "t": "IX - meio de transporte;"}, {"c": "dou-paragraph", "t": "X - dados, informações e documentos de relevância para a fiscalização;"}, {"c": "dou-paragraph", "t": "XI - volume e frequência de ingresso ou egresso; e"}, {"c": "dou-paragraph", "t": "XII - outros critérios definidos em normas técnicas específicas."}, {"c": "dou-paragraph", "t": "Parágrafo único. O canal de fiscalização agropecuária será baseado no gerenciamento/gestão de risco agropecuário das atividades de controle e fiscalização executadas nas operações de comércio e trânsito internacional de produtos técnicos, pré-misturas, agrotóxicos formulados e afins, previstas na legislação vigente e definida pela Coordenação Geral de Agrotóxicos e Afins."}, {"c": "dou-paragraph", "t": "Art. 21. Será necessário o registro do LPCO previamente ao embarque para:"}, {"c": "dou-paragraph", "t": "I - agrotóxicos formulados, produtos técnicos, pré-misturas e afins com Registro Especial Temporário (RET) ou autorizados;"}, {"c": "dou-paragraph", "t": "II - produtos técnicos, pré-misturas, agrotóxicos formulados e afins para pesquisa ou análise laboratorial que utilizem produtos à base de ingrediente ativo já registrado no país; e"}, {"c": "dou-paragraph", "t": "III - importadores autorizados como terceiros para importar agrotóxicos formulados, produtos técnicos, pré-misturas e afins já registrados."}, {"c": "dou-paragraph", "t": "§ 1º A autorização para importação poderá ser concedida por meio de critérios de gerenciamento/gestão de risco agropecuário para uma única ou múltiplas operações de importação, ambas realizadas dentro do prazo de vigência da autorização e no limite da quantidade autorizada."}, {"c": "dou-paragraph", "t": "§ 2º O prazo de vigência da autorização para importação será de cento e oitenta dias, podendo ser reduzido ou ampliado a depender da situação do importador e do produto junto ao Ministério da Agricultura e Pecuária e do gerenciamento/gestão de risco agropecuário aplicada pelo Serviço de Fiscalização responsável pela análise do processo."}, {"c": "dou-paragraph", "t": "§ 3º O importador poderá solicitar prorrogação ou retificação da autorização para importação mediante funcionalidade específica do LPCO, ficando sujeita a análise ao Serviço de Fiscalização competente das unidades descentralizadas do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 4º A autorização para importação poderá ser revogada a qualquer tempo, sem prévia comunicação ao importador, quando o importador ou o produto tiver sua situação junto ao Ministério da Agricultura e Pecuária suspensa ou cancelada, mediante medida cautelar ou decisão em processo administrativo; ou vencida pelo término de validade do registro ou autorização, conforme o caso."}, {"c": "dou-paragraph", "t": "Art. 22. O importador deverá registrar o LPCO com as seguintes informações:"}, {"c": "dou-paragraph", "t": "I - marca comercial ou código;"}, {"c": "dou-paragraph", "t": "II - categoria do produto;"}, {"c": "dou-paragraph", "t": "III - o número do registro do produto no Ministério da Agricultura e Pecuária ou da autorização;"}, {"c": "dou-paragraph", "t": "IV - a composição (ingrediente ativo e concentração);"}, {"c": "dou-paragraph", "t": "V - o tipo de formulação;"}, {"c": "dou-paragraph", "t": "VI - o tipo de embalagem, informando o material e a capacidade de acondicionamento;"}, {"c": "dou-paragraph", "t": "VII - quantidade a ser importada em litros ou quilos;"}, {"c": "dou-paragraph", "t": "VIII - nome completo do fabricante do produto técnico, indicando país de origem (local de fabricação), quando for o caso;"}, {"c": "dou-paragraph", "t": "IX - nome completo do formulador indicando o país de origem (local de formulação), quando for o caso;"}, {"c": "dou-paragraph", "t": "X - finalidade (comércio, fracionamento, uso na indústria, pesquisa ou análise laboratorial, retrabalho, revalidação ou reprocessamento);"}, {"c": "dou-paragraph", "t": "XI - registro de Pessoa Jurídica como Importador de produtos técnicos, pré-misturas, agrotóxicos formulados e afins; e"}, {"c": "dou-paragraph", "t": "XII - outras informações que o Ministério da Agricultura e Pecuária entender serem necessárias."}, {"c": "dou-paragraph", "t": "Art. 23. No registro do LPCO deverão ser anexados os seguintes documentos obrigatórios:"}, {"c": "dou-paragraph", "t": "I - documento eletrônico de RET; quando couber;"}, {"c": "dou-paragraph", "t": "II - documento de Autorização de Produto, quando couber;"}, {"c": "dou-paragraph", "t": "III - autorização de importador no caso de terceiros, quando autorizados por meio de ato publicado pelo Ministério da Agricultura e Pecuária no Diário Oficial da União ou seu sítio eletrônico;"}, {"c": "dou-paragraph", "t": "IV - alterações pós-registro autorizados por meio de ato publicado pelo Ministério da Agricultura e Pecuária no Diário Oficial da União ou seu sítio eletrônico que sejam pertinentes à importação e que não constem no Certificado de Registro do Produto;"}, {"c": "dou-paragraph", "t": "V - documento de Registro de Pessoa Jurídica como Importador de produtos técnicos, pré-misturas, agrotóxicos formulados e afins;"}, {"c": "dou-paragraph", "t": "VI - projeto de pesquisa quando a finalidade for pesquisa e/ou análise laboratorial; e"}, {"c": "dou-paragraph", "t": "VII - outros documentos que o Ministério da Agricultura e Pecuária entender serem necessários."}, {"c": "dou-paragraph", "t": "Parágrafo único. A quantidade importada de produtos técnicos, pré-misturas, agrotóxicos formulados e afins para pesquisa ou análise laboratorial que utilizem produtos à base de ingrediente ativo já registrado no país deve ser compatível com o projeto de pesquisa a que se destina."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Do controle agropecuário na importação de produtos técnicos, pré-misturas, agrotóxicos formulados e afins"}, {"c": "dou-paragraph", "t": "Art. 24. O controle agropecuário na importação de produtos técnicos, pré-misturas, agrotóxicos formulados e afins, dar-se-á por meio do módulo Declaração Única de Importação - Duimp, ou seu equivalente, no Portal Único de Comércio Exterior."}, {"c": "dou-paragraph", "t": "Art. 25. Para produto técnico, pré-mistura e produto formulado, o importador deverá prestar as seguintes informações na declaração de importação:"}, {"c": "dou-paragraph", "t": "I - marca comercial ou código;"}, {"c": "dou-paragraph", "t": "II - o número do registro do produto no Ministério da Agricultura e Pecuária ou autorização;"}, {"c": "dou-paragraph", "t": "III - a composição (ingrediente ativo e concentração);"}, {"c": "dou-paragraph", "t": "IV - o tipo de formulação;"}, {"c": "dou-paragraph", "t": "V - o tipo de embalagem, informando o material e a capacidade de acondicionamento;"}, {"c": "dou-paragraph", "t": "VI - número do lote ou partida que será empregado em sua rastreabilidade e a quantidade total produzida no lote ou partida;"}, {"c": "dou-paragraph", "t": "VII- data de fabricação e prazo de validade;"}, {"c": "dou-paragraph", "t": "VIII - quantidade a ser importada em litros ou quilos;"}, {"c": "dou-paragraph", "t": "IX- nome completo do fabricante do produto técnico, indicando país de origem (local de fabricação), quando for o caso;"}, {"c": "dou-paragraph", "t": "X- nome completo do formulador indicando o país de origem (local de formulação), quando for o caso;"}, {"c": "dou-paragraph", "t": "XI - finalidade (comércio, fracionamento, uso na indústria, pesquisa ou análise laboratorial, retrabalho, revalidação ou reprocessamento, devolução do exterior);"}, {"c": "dou-paragraph", "t": "XII - endereço de destino da mercadoria ao sair da área alfandegada; e"}, {"c": "dou-paragraph", "t": "XIII - outras informações que o Ministério da Agricultura e Pecuária entender serem necessárias."}, {"c": "dou-paragraph", "t": "Art. 26. Na declaração de importação de produtos técnicos, pré-misturas, agrotóxicos formulados e afins, independente do canal de fiscalização selecionado, deverão ser anexados os seguintes documentos obrigatórios:"}, {"c": "dou-paragraph", "t": "I - alterações pós-registro autorizados por meio de ato publicado pelo Ministério da Agricultura e Pecuária no Diário Oficial da União ou seu sítio eletrônico que sejam pertinentes à importação e que não constem no Certificado de Registro do Produto;"}, {"c": "dou-paragraph", "t": "II - documento de Registro de Pessoa Jurídica como Importador de produtos técnicos, pré-misturas, agrotóxicos formulados e afins;"}, {"c": "dou-paragraph", "t": "III - fatura (invoice);"}, {"c": "dou-paragraph", "t": "IV - romaneio de carga (packing list); e"}, {"c": "dou-paragraph", "t": "V- outros documentos que o Ministério da Agricultura e Pecuária entender serem necessários."}, {"c": "dou-paragraph", "t": "Parágrafo único. No caso da declaração de importação estar vinculada a um LPCO fica dispensada a anexação dos documentos dos incisos I e II."}, {"c": "dou-paragraph", "t": "Art. 27. Agrotóxicos formulados e afins deverão apresentar rótulos e bulas próprios, redigidos em português conforme o art. 43 da Lei nº 14.785, de 27 de dezembro de 2023, e normas complementares."}, {"c": "dou-paragraph", "t": "Art. 28. Produtos técnicos, pré-misturas, agrotóxicos formulados e afins para pesquisa ou análise laboratorial e produtos formulados para fracionamento em ambiente industrial deverão apresentar as seguintes informações mínimas para rotulagem redigidas em português:"}, {"c": "dou-paragraph", "t": "I - produtos técnicos:"}, {"c": "dou-paragraph", "t": "a) nome do produto ou nome(s) do(s) produto(s) técnico(s) vinculado(s);"}, {"c": "dou-paragraph", "t": "b) nome do registrante e/ou importador;"}, {"c": "dou-paragraph", "t": "c) nome químico e/ou comum de acordo com o Certificado de Registro;"}, {"c": "dou-paragraph", "t": "d) classe de uso conforme descrito no Certificado de Registro;"}, {"c": "dou-paragraph", "t": "e) número do Registro do produto no Ministério da Agricultura e Pecuária e número do CAS;"}, {"c": "dou-paragraph", "t": "f) concentração mínima, conforme Certificado de Registro;"}, {"c": "dou-paragraph", "t": "g) nome e endereço completo do fabricante indicando país de origem (local de fabricação);"}, {"c": "dou-paragraph", "t": "h) número do lote;"}, {"c": "dou-paragraph", "t": "i) data de fabricação e vencimento;"}, {"c": "dou-paragraph", "t": "j) quantidade de produto que a embalagem contém, expressa em unidades de peso ou volume, conforme o caso;"}, {"c": "dou-paragraph", "t": "k) indicação de que o produto se destina ao uso industrial; e"}, {"c": "dou-paragraph", "t": "l) classe toxicológica, de acordo com Sistema Globalmente Harmonizado de Classificação e Rotulagem de Produtos Químicos (GHS);"}, {"c": "dou-paragraph", "t": "II - pré-misturas:"}, {"c": "dou-paragraph", "t": "a) nome(s) do(s) produto(s) técnico(s) vinculado(s);"}, {"c": "dou-paragraph", "t": "b) nome do registrante e/ou importador;"}, {"c": "dou-paragraph", "t": "c) nome químico e/ou comum de acordo com o Certificado de Registro;"}, {"c": "dou-paragraph", "t": "d) classe de uso conforme descrito no Certificado de Registro;"}, {"c": "dou-paragraph", "t": "e) número do Registro do produto no Ministério da Agricultura e Pecuária e número do CAS;"}, {"c": "dou-paragraph", "t": "f) concentração mínima, conforme Certificado de Registro;"}, {"c": "dou-paragraph", "t": "g) nome e endereço completo do fabricante indicando país de origem (local de fabricação);"}, {"c": "dou-paragraph", "t": "h) número do lote;"}, {"c": "dou-paragraph", "t": "i) data de fabricação e vencimento;"}, {"c": "dou-paragraph", "t": "j) quantidade de produto que a embalagem contém, expressa em unidades de peso ou volume, conforme o caso;"}, {"c": "dou-paragraph", "t": "k) Indicação de que o produto se destina ao uso industrial; e"}, {"c": "dou-paragraph", "t": "l) classe toxicológica, de acordo com Sistema Globalmente Harmonizado de Classificação e Rotulagem de Produtos Químicos (GHS);"}, {"c": "dou-paragraph", "t": "III - produtos formulados para fracionamento em ambiente industrial:"}, {"c": "dou-paragraph", "t": "a) nome do produto (nome comercial);"}, {"c": "dou-paragraph", "t": "b) nome do registrante e importador;"}, {"c": "dou-paragraph", "t": "c) nome químico e/ou comum de acordo com o certificado de registro;"}, {"c": "dou-paragraph", "t": "d) classe de uso conforme descrito no certificado de registro;"}, {"c": "dou-paragraph", "t": "e) número do Registro do produto no Ministério da Agricultura e Pecuária;"}, {"c": "dou-paragraph", "t": "f) tipo de formulação;"}, {"c": "dou-paragraph", "t": "g) percentagem e/ou a indicação da concentração de cada princípio ativo, de acordo com o Certificado de Registro;"}, {"c": "dou-paragraph", "t": "h) nome e endereço completo do fabricante do Produto Técnico indicando país de origem (local de fabricação);"}, {"c": "dou-paragraph", "t": "i) nome e endereço completo do formulador, indicando o país de origem (local de formulação);"}, {"c": "dou-paragraph", "t": "j) número do lote, data de fabricação e vencimento;"}, {"c": "dou-paragraph", "t": "k) quantidade de produto que a embalagem contém, expressa em unidades de peso ou volume, conforme o caso;"}, {"c": "dou-paragraph", "t": "l) indicação de que o produto não se destina à comercialização ou ao usuário final; e"}, {"c": "dou-paragraph", "t": "m) classe toxicológica, de acordo com Sistema Globalmente Harmonizado de Classificação e Rotulagem de Produtos Químicos (GHS); e"}, {"c": "dou-paragraph", "t": "IV - produtos formulados para pesquisa ou análise laboratorial:"}, {"c": "dou-paragraph", "t": "a) nome ou código do produto;"}, {"c": "dou-paragraph", "t": "b) nome do titular do registro;"}, {"c": "dou-paragraph", "t": "c) número do RET ou autorização quando couber;"}, {"c": "dou-paragraph", "t": "d) nome do ingrediente ativo;"}, {"c": "dou-paragraph", "t": "e) concentração do ingrediente ativo;"}, {"c": "dou-paragraph", "t": "f) nome e endereço do fabricante;"}, {"c": "dou-paragraph", "t": "g) nome e endereço do formulador;"}, {"c": "dou-paragraph", "t": "h) quantidade, expressa em unidade de peso ou volume, conforme o caso;"}, {"c": "dou-paragraph", "t": "i) data de fabricação; e"}, {"c": "dou-paragraph", "t": "j) data de vencimento."}, {"c": "dou-paragraph", "t": "Parágrafo único. Em caso de embalagens onde não seja possível a fixação da rotulagem, as informações deverão constar em bolsas acessórias à embalagem."}, {"c": "dou-paragraph", "t": "Art. 29. Informações adicionais poderão constar dos rótulos e embalagens, de acordo com os procedimentos internacionais de transporte e as diretrizes de cada empresa, sendo permitido o uso de código de resposta rápida (QR Code) e similares."}, {"c": "dou-paragraph", "t": "Art. 30. Na análise da declaração de importação, quando constatada irregularidade, considerada como ação ou omissão que viole a legislação vigente, relacionada à documentação, embalagem e/ou rotulagem; a declaração de importação deverá ser colocada em exigência no sistema se passível de correção ou no caso de proibição de ingresso deverá ser excluída e submetida às medidas impostas pela fiscalização agropecuária."}, {"c": "dou-paragraph", "t": "§ 1º Toda irregularidade documental deverá ser sanada no curso da análise da Vigilância Agropecuária Internacional, sem autorização para entrega antecipada da mercadoria."}, {"c": "dou-paragraph", "t": "§ 2º Mediante solicitação do interessado, considerando questões operacionais, poderá a Vigilância Agropecuária Internacional autorizar a correção das irregularidades físicas da mercadoria na própria área alfandegada, somente nos casos de troca de rotulagem de produto para a pesquisa ou análise laboratorial, dispensada a manifestação técnica pelo Serviço de Fiscalização competente na UF de jurisdição do importador."}, {"c": "dou-paragraph", "t": "§ 3º No caso de não cumprimento da exigência no prazo determinado, ainda dentro da área alfandegada, a medida imposta pela fiscalização agropecuária será a devolução da mercadoria ao exterior ou destruição."}, {"c": "dou-paragraph", "t": "§ 4º Será lavrado auto de infração pelo Serviço de Fiscalização da Superintendência na Unidade da Federação da jurisdição do importador, com posterior instauração e condução das demais fases do processo administrativo fiscal, sem prejuízo da responsabilidade civil e penal, no caso de irregularidade documental e/ou física registrada no ingresso da mercadoria e sanada dentro da área alfandegada no prazo estabelecido pelo Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 5º Não será autorizada correção de irregularidades físicas (embalagem e/ou rotulagem) da mercadoria fora da área alfandegada."}, {"c": "dou-paragraph", "t": "Art. 31. A Coordenação-Geral de Agrotóxicos e Afins estabelecerá a metodologia e os procedimentos de fiscalização por amostragem baseada em critérios de gerenciamento/gestão de risco para:"}, {"c": "dou-paragraph", "t": "I - coleta de amostra para análise de controle ou análise de fiscalização;"}, {"c": "dou-paragraph", "t": "II - coleta de amostras para fins de investigação, apuração de denúncia, ou formação de banco de dados para subsidiar metodologias laboratoriais que visam detectar fraudes em produtos;"}, {"c": "dou-paragraph", "t": "III - quantidade de embalagens a ser inspecionada; e"}, {"c": "dou-paragraph", "t": "IV - processos de importação a serem fiscalizados."}, {"c": "dou-paragraph", "t": "Art. 32. A Coordenação-Geral de Agrotóxicos e Afins, embasada por critérios de gerenciamento/gestão de risco, informará à Vigilância Agropecuária Internacional a necessidade de coleta de amostras dos produtos previstos nesta norma, para fins de controle de qualidade."}, {"c": "dou-paragraph", "t": "Art. 33. A pedido do importador, devidamente formalizado na declaração de importação, antes da liberação agropecuária, poderá ser autorizada a entrega antecipada da mercadoria no caso de coleta de amostra para análise de controle ou análise de fiscalização."}, {"c": "dou-paragraph", "t": "Art. 34. Para a entrega antecipada o importador se compromete a:"}, {"c": "dou-paragraph", "t": "I - não consumir, comercializar, utilizar, manipular a mercadoria, ou de qualquer forma alterar as suas características, até a conclusão do processo de importação;"}, {"c": "dou-paragraph", "t": "II - aceitar o encargo de depositário da mercadoria;"}, {"c": "dou-paragraph", "t": "III - assumir as condições impostas pelo Ministério da Agricultura e Pecuária para a concessão da entrega antecipada; e"}, {"c": "dou-paragraph", "t": "IV - cumprir as medidas impostas pela fiscalização em razão do resultado da análise de controle ou de fiscalização."}, {"c": "dou-paragraph", "t": "Art. 35. Caberá ao Auditor Fiscal Federal Agropecuário responsável pelo processo de importação analisar o pedido de entrega antecipada da mercadoria."}, {"c": "dou-paragraph", "t": "Art. 36. A entrega antecipada não implica na liberação agropecuária da importação, ficando a conclusão do processo de importação pendente do resultado da análise laboratorial."}, {"c": "dou-paragraph", "t": "§ 1º Constatada a conformidade do resultado da análise laboratorial de controle ou de fiscalização, a liberação agropecuária será efetuada pela Vigilância Agropecuária Internacional ou pelo Serviço de Fiscalização responsável pela análise do processo."}, {"c": "dou-paragraph", "t": "§ 2º Constatada não conformidade no resultado da análise laboratorial de controle ou fiscalização serão adotados os procedimentos previstos na legislação vigente."}, {"c": "dou-paragraph", "t": "Art. 37. O descumprimento das condições para a entrega antecipada impede o importador e todas as suas filiais de solicitar novas autorizações para entrega antecipada em um período de doze meses, sem prejuízo das responsabilizações civis e administrativas, conforme o caso."}, {"c": "dou-paragraph", "t": "Art. 38. Em caso de devolução ao exterior ou destruição da mercadoria, o responsável pela importação acatará, sem qualquer restrição ou ônus para o Ministério da Agricultura e Pecuária, as exigências e providências previstas na legislação vigente."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Da exportação de produtos técnicos, pré-misturas, agrotóxicos formulados e afins"}, {"c": "dou-paragraph", "t": "Art. 39. Somente poderão exportar produtos técnicos, pré-misturas, agrotóxicos formulados e afins, as empresas titulares de registro do produto ou suas filiais."}, {"c": "dou-paragraph", "t": "Art. 40. O controle agropecuário na exportação de agrotóxicos formulados, produtos técnicos, pré-misturas e afins, dar-se-á por meio do módulo LPCO, ou seu equivalente, no Portal Único de Comércio Exterior."}, {"c": "dou-paragraph", "t": "Art. 41. Será necessário o registro do LPCO para:"}, {"c": "dou-paragraph", "t": "I- agrotóxicos formulados e afins destinados exclusivamente para exportação;"}, {"c": "dou-paragraph", "t": "II- produtos técnicos, pré-misturas, agrotóxicos formulados e afins com a finalidade de exportação temporária para aperfeiçoamento passivo; e"}, {"c": "dou-paragraph", "t": "III - produtos técnicos, pré-misturas, agrotóxicos formulados e afins registrados no Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 1º A autorização para exportação poderá ser concedida para uma única ou múltiplas operações de exportação, ambas realizadas dentro do prazo de vigência da autorização e no limite da quantidade autorizada."}, {"c": "dou-paragraph", "t": "§ 2º O prazo de vigência da autorização para exportação será de trezentos e sessenta e cinco dias, podendo ser reduzido ou ampliado a depender da situação do exportador e do produto junto ao Ministério da Agricultura e Pecuária aplicada pelo Serviço de Fiscalização responsável pela análise do processo."}, {"c": "dou-paragraph", "t": "§ 3º O exportador poderá solicitar prorrogação ou retificação da autorização para exportação mediante funcionalidade específica do LPCO, ficando sujeita a análise ao Serviço de Fiscalização competente das unidades descentralizadas do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 4º A autorização para exportação poderá ser revogada a qualquer tempo, sem prévia comunicação ao exportador, quando o exportador ou o produto tiver sua situação junto ao Ministério da Agricultura e Pecuária suspensa ou cancelada, mediante medida cautelar ou decisão em processo administrativo; ou vencida pelo término de validade do registro ou autorização, conforme o caso."}, {"c": "dou-paragraph", "t": "Art. 42. O exportador deverá registrar o LPCO com as seguintes informações:"}, {"c": "dou-paragraph", "t": "I - marca comercial ou código;"}, {"c": "dou-paragraph", "t": "II - categoria do produto;"}, {"c": "dou-paragraph", "t": "III - o número do registro do produto no Ministério da Agricultura e Pecuária ou número do documento específico emitido pelo Ministério da Agricultura e Pecuária para exportação;"}, {"c": "dou-paragraph", "t": "IV - a composição (ingrediente ativo e concentração);"}, {"c": "dou-paragraph", "t": "V - o tipo de formulação;"}, {"c": "dou-paragraph", "t": "VI - o tipo de embalagem, informando o material e a capacidade de acondicionamento;"}, {"c": "dou-paragraph", "t": "VII - quantidade a ser exportada em litros ou quilos;"}, {"c": "dou-paragraph", "t": "VIII- nome completo e endereço do fabricante do produto técnico, quando for o caso;"}, {"c": "dou-paragraph", "t": "IX - nome completo do formulador indicando o país de origem (local de formulação), quando for o caso;"}, {"c": "dou-paragraph", "t": "X - finalidade (comércio, pesquisa ou análise laboratorial, retrabalho, revalidação ou reprocessamento, proibição de ingresso ou/devolução ao exterior);"}, {"c": "dou-paragraph", "t": "XI - registro de Pessoa Jurídica como Exportador de produtos técnicos, pré-misturas, agrotóxicos formulados e afins; e"}, {"c": "dou-paragraph", "t": "XII - outras informações que o Ministério da Agricultura e Pecuária entender serem necessárias."}, {"c": "dou-paragraph", "t": "Art. 43. No registro do LPCO deverão ser anexados os seguintes documentos obrigatórios:"}, {"c": "dou-paragraph", "t": "I - documento específico emitido pelo Ministério da Agricultura e Pecuária para exportação para agrotóxicos formulados e afins destinados exclusivamente para exportação;"}, {"c": "dou-paragraph", "t": "II - extrato da DUIMP no caso dos produtos com a finalidade de exportação temporária para aperfeiçoamento passivo;"}, {"c": "dou-paragraph", "t": "III - documento de Registro de Pessoa Jurídica como Exportador de produtos técnicos, pré-misturas, agrotóxicos formulados e afins;"}, {"c": "dou-paragraph", "t": "IV - fatura (invoice);"}, {"c": "dou-paragraph", "t": "V - romaneio de carga (packing list); e"}, {"c": "dou-paragraph", "t": "VI - outros documentos que o Ministério da Agricultura e Pecuária entender serem necessários."}, {"c": "dou-paragraph", "t": "Parágrafo único. No caso de múltiplos embarques, os itens IV e V deverão ser anexados ao LPCO a cada diferente embarque."}, {"c": "dou-paragraph", "t": "Art. 44. A rotulagem dos produtos técnicos, pré-misturas, agrotóxicos formulados e afins destinados para exportação poderão ser escritos no todo ou em parte no idioma do país de destino conforme a exigência daquele país, sendo os dizeres da rotulagem de inteira responsabilidade do fabricante."}, {"c": "dou-paragraph", "t": "§ 1º Agrotóxicos formulados e afins exclusivamente para exportação deverão apresentar em seu rótulo o número de registro do estabelecimento no Ministério da Agricultura e Pecuária, a identificação do lote e a expressão \"Indústria Brasileira\" ou que o produto foi fabricado no Brasil escrito em português."}, {"c": "dou-paragraph", "t": "§ 2º Produtos técnicos, pré-misturas, agrotóxicos formulados e afins registrados e destinados para exportação deverão apresentar em seu rótulo o número de registro do estabelecimento no Ministério da Agricultura e Pecuária, o nome ou o número de registro do produto, a identificação do lote e a expressão \"Indústria Brasileira\" ou que o produto foi fabricado no Brasil escrito em português."}, {"c": "dou-paragraph", "t": "CAPÍTULO III"}, {"c": "dou-paragraph", "t": "DA IMPORTAÇÃO E DA EXPORTAÇÃO DE FERTILIZANTES E CORRELATOS"}, {"c": "dou-paragraph", "t": "Art. 45. As disposições deste Capítulo aplicam-se a toda importação e exportação de fertilizantes, corretivos, inoculantes, biofertilizantes, remineralizadores, substratos para plantas e suas matérias-primas, uma vez atendidas as legislações pertinentes do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 46. Para a importação e a exportação dos produtos especificados neste Capítulo e de suas matérias-primas será exigido registro no Ministério da Agricultura e Pecuária do estabelecimento responsável pela importação ou exportação e do produto, ou autorização específica, quando for o caso."}, {"c": "dou-paragraph", "t": "Parágrafo único. Sem prejuízo do disposto nos arts. 45 e 46 do regulamento aprovado pelo Decreto nº 4.954, de 14 de janeiro de 2004, alterado pelo Decreto nº 8.059, de 26 de julho de 2013, os produtos adquiridos no mercado externo por estabelecimentos produtores como matéria-prima para utilização na produção serão dispensados de registro, sendo vedada a sua revenda nessa condição, excetuado a sua transferência para outras unidades de estabelecimentos da mesma empresa ou remessa para industrialização."}, {"c": "dou-paragraph", "t": "Art. 47. Somente poderão importar fertilizantes, corretivos, inoculantes, biofertilizantes, remineralizadores e substratos para plantas as empresas titulares de registro de produto ou suas filiais registradas na mesma atividade."}, {"c": "dou-paragraph", "t": "Parágrafo único. A importação de inóculo de bioinsumo para produção de uso próprio dependerá do registro, conforme § 6º do art. 14 da Lei nº 15.070, de 23 de dezembro de 2024."}, {"c": "dou-paragraph", "t": "Art. 48. Ficam dispensados de registro de produto e estabelecimento no Ministério da Agricultura e Pecuária:"}, {"c": "dou-paragraph", "t": "I - os fertilizantes, corretivos, biofertilizantes, remineralizadores e substratos para plantas importados diretamente pelo consumidor final para uso próprio;"}, {"c": "dou-paragraph", "t": "II - as amostras destinadas à pesquisa e experimentação; e"}, {"c": "dou-paragraph", "t": "III - as amostras destinadas à análise laboratorial."}, {"c": "dou-paragraph", "t": "§ 1º As cooperativas agropecuárias se equiparam ao consumidor final, quando realizarem importações para uso exclusivo de seus cooperados, conforme caracterizado no ato cooperativo, de acordo com a Lei nº 5.764, de 16 de dezembro de 1971."}, {"c": "dou-paragraph", "t": "§ 2º As amostras de produtos destinadas à de pesquisa e experimentação e à análise laboratorial deverão estar embaladas."}, {"c": "dou-paragraph", "t": "§ 3º É vedada a importação de bioinsumos para uso próprio que contenha microrganismo como princípio ativo, conforme § 5º do art. 14 da Lei nº 15.070, de 23 de dezembro de 2024."}, {"c": "dou-paragraph", "t": "Art. 49. Para os casos de dispensa de registro de produto prevista no art. 48, a importação dependerá de autorização prévia concedida pela área técnica competente por meio de LPCO."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Da autorização para importação de fertilizantes e correlatos"}, {"c": "dou-paragraph", "t": "Art. 50. Quando exigida, a autorização do Ministério da Agricultura e Pecuária para a importação de fertilizantes, corretivos, inoculantes, biofertilizantes, remineralizadores, substratos para plantas e suas matérias primas deverá ser solicitada pelo registro do LPCO contendo as seguintes informações:"}, {"c": "dou-paragraph", "t": "I - razão social do importador;"}, {"c": "dou-paragraph", "t": "II - CNPJ do importador;"}, {"c": "dou-paragraph", "t": "III - número de registro do estabelecimento no Ministério da Agricultura e Pecuária, exceto nos casos previstos no art. 48;"}, {"c": "dou-paragraph", "t": "IV - número de registro do produto no Ministério da Agricultura e Pecuária, exceto nos casos previstos no art. 48 e de importação de matéria-prima;"}, {"c": "dou-paragraph", "t": "V - finalidade da importação, podendo ser produção, comercialização, uso próprio-produtor rural ou empresa agrícola ou uso próprio-cooperativa, pesquisa e experimentação, análise laboratorial ou retorno de exportação;"}, {"c": "dou-paragraph", "t": "VI - país de origem;"}, {"c": "dou-paragraph", "t": "VII - país de procedência;"}, {"c": "dou-paragraph", "t": "VIII - Nomenclatura Comum Mercosul - NCM;"}, {"c": "dou-paragraph", "t": "IX - quantidade e peso líquido;"}, {"c": "dou-paragraph", "t": "X - evento OGM, quando for o caso;"}, {"c": "dou-paragraph", "t": "XI - especificação do material (composição e garantias);"}, {"c": "dou-paragraph", "t": "XII - categoria;"}, {"c": "dou-paragraph", "t": "XIII - natureza física do produto: sólido ou fluido;"}, {"c": "dou-paragraph", "t": "XIV - tipo de embalagem: granel ou embalado;"}, {"c": "dou-paragraph", "t": "XV- local de destino;"}, {"c": "dou-paragraph", "t": "XVI - local onde o material ficará depositado;"}, {"c": "dou-paragraph", "t": "XVII - local da quarentena ou o laboratório de diagnóstico fitossanitário, quando for o caso; e"}, {"c": "dou-paragraph", "t": "XVIII - número da DU-E em caso de retorno de exportação."}, {"c": "dou-paragraph", "t": "Art. 51. Deverão ser anexados ao LPCO de autorização para importação:"}, {"c": "dou-paragraph", "t": "I - no caso de importação por consumidor final - produtor rural ou empresa agrícola:"}, {"c": "dou-paragraph", "t": "a) cópia da inscrição como produtor rural ou como empresa agrícola, junto à Secretaria Estadual de Fazenda ou órgão equivalente;"}, {"c": "dou-paragraph", "t": "b) contrato social, para empresa agrícola, no qual o objeto social mencione o cultivo de vegetais;"}, {"c": "dou-paragraph", "t": "c) certificado de livre comércio e consumo corrente do produto ou registro do produto no país de origem;"}, {"c": "dou-paragraph", "t": "d) ficha técnica do produto com composição e garantias;"}, {"c": "dou-paragraph", "t": "e) termo de compromisso conforme modelo constante do Anexo I; e"}, {"c": "dou-paragraph", "t": "f) plano de adubação, emitido por profissional legalmente habilitado, caracterizando a indicação do produto a ser importado para a (s) área (s) e cultura (s) especificada (s) no requerimento;"}, {"c": "dou-paragraph", "t": "II - no caso de importação por consumidor final - cooperativas agropecuárias:"}, {"c": "dou-paragraph", "t": "a) cópia do estatuto social;"}, {"c": "dou-paragraph", "t": "b) relação nominal dos cooperados que utilizarão o insumo a ser importado, com indicação da quantidade por cooperado;"}, {"c": "dou-paragraph", "t": "c) certificado de livre comércio e consumo corrente do produto ou registro do produto no país de origem;"}, {"c": "dou-paragraph", "t": "d) ficha técnica do produto com composição e garantias;"}, {"c": "dou-paragraph", "t": "e) termo de compromisso conforme modelo constante do Anexo II; e"}, {"c": "dou-paragraph", "t": "f) plano de adubação, emitido por profissional legalmente habilitado, caracterizando a indicação do produto a ser importado para a (s) área (s) e cultura (s) especificada (s) no requerimento;"}, {"c": "dou-paragraph", "t": "III - no caso de importação de amostra destinadas à de pesquisa e experimentação:"}, {"c": "dou-paragraph", "t": "a) projeto técnico de pesquisa elaborado por instituição pública ou privada de pesquisa credenciada no Ministério da Agricultura e Pecuária, contendo:"}, {"c": "dou-paragraph", "t": "1. as seguintes informações da instituição de pesquisa:"}, {"c": "dou-paragraph", "t": "1.1. razão social;"}, {"c": "dou-paragraph", "t": "1.2. CNPJ;"}, {"c": "dou-paragraph", "t": "1.3. número da portaria de credenciamento, no caso de instituição privada;"}, {"c": "dou-paragraph", "t": "1.4. endereço completo;"}, {"c": "dou-paragraph", "t": "1.5. telefone; e"}, {"c": "dou-paragraph", "t": "1.6. correio eletrônico (e-mail);"}, {"c": "dou-paragraph", "t": "2. a caracterização do produto, quanto à composição, processo produtivo e garantias;"}, {"c": "dou-paragraph", "t": "3. as etapas da pesquisa e as quantidades necessárias para cada uma delas, incluindo estimativa de perdas;"}, {"c": "dou-paragraph", "t": "4. o local onde o material ficará armazenado até a instalação dos ensaios;"}, {"c": "dou-paragraph", "t": "5. os locais de instalação dos ensaios, com endereço completo e coordenadas geográficas;"}, {"c": "dou-paragraph", "t": "6. as datas prováveis de instalação dos ensaios;"}, {"c": "dou-paragraph", "t": "7. as culturas utilizadas;"}, {"c": "dou-paragraph", "t": "8. o delineamento experimental e número de repetições; e"}, {"c": "dou-paragraph", "t": "9. a informação quanto à importação em múltiplos embarques por etapa, com as respectivas quantidades, ou se será feita importação única do valor total;"}, {"c": "dou-paragraph", "t": "b) certificado de livre comércio e consumo corrente do produto ou registro do produto no país de origem; e"}, {"c": "dou-paragraph", "t": "c) termo de compromisso conforme modelo constante do Anexo III; e"}, {"c": "dou-paragraph", "t": "IV - no caso de importação de amostra destinadas à de análise laboratorial:"}, {"c": "dou-paragraph", "t": "a) indicação do laboratório responsável pelas análises;"}, {"c": "dou-paragraph", "t": "b) lista de determinações a serem realizadas;"}, {"c": "dou-paragraph", "t": "c) volume de amostra necessária por analito; e"}, {"c": "dou-paragraph", "t": "d) termo de compromisso conforme modelo constante do Anexo IV."}, {"c": "dou-paragraph", "t": "§ 1º O fertilizante, corretivo, inoculante, biofertilizante, remineralizador ou substrato para plantas novo, nos termos do art. 15 do Anexo ao Decreto nº 4.954, de 14 de janeiro de 2004, não terá sua importação autorizada, exceto quando se tratar de importação de amostra para pesquisa e experimentação ou para análise laboratorial."}, {"c": "dou-paragraph", "t": "§ 2º Os produtos importados como amostra para pesquisa e experimentação ou para análise laboratorial devem ser registrados no país de origem ou serem de livre comércio e consumo corrente na mesma categoria prevista na legislação brasileira, ou sua equivalente."}, {"c": "dou-paragraph", "t": "§ 3º O certificado de livre comércio e consumo corrente do produto poderá ser substituído por declaração de mesmo conteúdo feita pela empresa em papel timbrado, assinada pelo representante legal, com chancela de Câmara de Comércio que ateste a veracidade das informações."}, {"c": "dou-paragraph", "t": "Art. 52. A autorização para importação terá validade de:"}, {"c": "dou-paragraph", "t": "I - cento e oitenta dias, quando concedida para uma única operação; e"}, {"c": "dou-paragraph", "t": "II - trezentos e sessenta e cinco dias, quando concedida para múltiplas operações."}, {"c": "dou-paragraph", "t": "§ 1º Os prazos previstos nos incisos I e II estão condicionados à validade do registro do importador e do registro do produto perante o Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "§ 2º As autorizações previstas no art. 48 poderão ser concedidas para múltiplas operações, limitadas ao saldo autorizado, exceto para importação de amostra para análise laboratorial, que será concedida para uma única operação."}, {"c": "dou-paragraph", "t": "§ 3º A autorização para importação de amostra para pesquisa e experimentação será válida para múltiplas operações quando o projeto de pesquisa exigir etapas diferentes de instalação, e quando a validade da amostra inviabilizar a importação única da quantidade total necessária para o experimento."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Do controle agropecuário na importação de fertilizantes e correlatos"}, {"c": "dou-paragraph", "t": "Art. 53. O controle agropecuário no momento da importação, para fins de liberação agropecuária, deverá ser solicitado após o deferimento do LPCO, pelo registro da Duimp contendo as seguintes informações:"}, {"c": "dou-paragraph", "t": "I - via de transporte;"}, {"c": "dou-paragraph", "t": "II - ponto de ingresso;"}, {"c": "dou-paragraph", "t": "III - unidade de despacho;"}, {"c": "dou-paragraph", "t": "IV - local de destino; e"}, {"c": "dou-paragraph", "t": "V - local onde o material ficará depositado, quando for ocaso."}, {"c": "dou-paragraph", "t": "Parágrafo único. O registro de Duimp para produtos dispensados de autorização para importação, também conterá as informações previstas no art. 50."}, {"c": "dou-paragraph", "t": "Art. 54. Deverão ser anexados à Duimp:"}, {"c": "dou-paragraph", "t": "I - cópia do certificado de análise;"}, {"c": "dou-paragraph", "t": "II- cópia do certificado de registro de estabelecimento produtor ou importador, quando exigido;"}, {"c": "dou-paragraph", "t": "III - cópia do certificado de registro do produto, quando exigido;"}, {"c": "dou-paragraph", "t": "IV - Certificado Fitossanitário, quando se tratar de produtos que possam abrigar pragas, observado o disposto nos arts 45 e 46 do Anexo ao Decreto nº 4.954, de 14 de janeiro de 2004; e"}, {"c": "dou-paragraph", "t": "V - cópia da nota fiscal ou cópia da fatura comercial (invoice)."}, {"c": "dou-paragraph", "t": "§ 1º O certificado de análise referente à partida importada deverá ser emitido por laboratório do país de origem e deverá conter resultados para todas as garantias registradas e declaradas, além dos contaminantes definidos em norma específica, expressos nas unidades utilizadas pela legislação brasileira de fertilizantes, corretivos, inoculantes, biofertilizantes, remineralizadores e substratos para plantas."}, {"c": "dou-paragraph", "t": "§ 2º Os certificados de análise mencionados no § 1º deverão seguir o padrão internacional ISO/IEC ou serem elaborados em papel timbrado do laboratório, emitidos em até trinta dias após a partida do material, contendo, no mínimo:"}, {"c": "dou-paragraph", "t": "I - número do lote referente ao produto importado;"}, {"c": "dou-paragraph", "t": "II - data da coleta e da análise;"}, {"c": "dou-paragraph", "t": "III - análises e métodos analíticos utilizados;"}, {"c": "dou-paragraph", "t": "IV - resultados expressos nas unidades utilizadas pela legislação brasileira; e"}, {"c": "dou-paragraph", "t": "V - identificação e assinatura do responsável pela análise e do laboratório."}, {"c": "dou-paragraph", "t": "Art. 55. A Coordenação-Geral de Fertilizantes, Inoculantes e Corretivos - CGFIC estabelecerá a metodologia de fiscalização por amostragem para coleta de amostra, quantidade de embalagens a inspecionar e processos a fiscalizar, baseada em critérios de gestão de risco."}, {"c": "dou-paragraph", "t": "Art. 56. A necessidade de coleta de amostra para análise fiscal dos atributos de identidade e qualidade será indicada no LPCO, quando da aprovação, e ocorrerá no local de despacho de importação perante o Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 57. A coleta de amostra para análise fitossanitária, quando exigida, ocorrerá no local de despacho de importação perante o Ministério da Agricultura e Pecuária, conforme definição do órgão técnico central de sanidade vegetal."}, {"c": "dou-paragraph", "t": "Art. 58. A entrega antecipada da mercadoria poderá ser autorizada quando a liberação agropecuária depender do resultado da análise fiscal ou fitossanitária."}, {"c": "dou-paragraph", "t": "Art. 59. Aos estabelecimentos produtores integrantes do Programa de Incentivo à Conformidade em Defesa Agropecuária poderá ser autorizada a entrega antecipada para fins de correção de informações de rótulo que não prejudiquem a identidade e a rastreabilidade do produto, desde que não haja indícios de dolo ou má-fé e inexistam débitos com a União, limitada a uma liberação por ano por este motivo."}, {"c": "dou-paragraph", "t": "Art. 60. É vedada a venda e a disposição para o comércio dos produtos importados pelo consumidor final ou importados como amostra para pesquisa e experimentação ou para análise laboratorial."}, {"c": "dou-paragraph", "t": "§ 1º O descumprimento do caput acarretará o cancelamento das autorizações emitidas para o interessado e suas filiais, bem como a proibição de emissão de novas autorizações em favor do mesmo e suas filiais, por prazo de vinte e quatro meses, sem prejuízo das penalidades previstas em norma específica."}, {"c": "dou-paragraph", "t": "§ 2º As sobras de amostra importada para pesquisa e experimentação e análise laboratorial deverão ser destruídas ou devolvidas à origem."}, {"c": "dou-paragraph", "t": "Art. 61. As embalagens dos produtos devem obedecer às regras estabelecidas em norma específica."}, {"c": "dou-paragraph", "t": "§ 1º No caso de matéria-prima, a embalagem deve conter, no mínimo, as informações de identificação do país de origem, do fabricante, número de lote, identificação do produto quanto à composição e componentes de garantia, e data de validade."}, {"c": "dou-paragraph", "t": "§ 2º A embalagem de amostra para pesquisa e experimentação ou para análise laboratorial deve conter, no mínimo, as informações de identificação do país de origem, do fabricante, número de lote, identificação do produto quanto à composição e componentes de garantia, e data de validade, o número do LPCO de autorização emitida pelo Ministério da Agricultura e Pecuária e a expressão: \"AMOSTRA - PROIBIDA A COMERCIALIZAÇÃO\"."}, {"c": "dou-paragraph", "t": "Art. 62. As embalagens de produto importado para uso próprio, bem como as notas fiscais, quando importado a granel, deverão constar as especificações do produto, o número do LPCO de autorização emitida pelo Ministério da Agricultura e Pecuária e a expressão: \"PRODUTO PARA USO PRÓPRIO - PROIBIDA A COMERCIALIZAÇÃO\", para importações feitas pelo consumidor final, ou \"PRODUTO PARA USO EXCLUSIVO DOS COOPERADOS DA COOPERATIVA (NOME DA COOPERATIVA)\", para as importações realizadas por cooperativas agropecuárias."}, {"c": "dou-paragraph", "t": "Parágrafo único. A manipulação do produto importado a granel pelo consumidor final somente poderá ser realizada por estabelecimento produtor, registrado no Ministério da Agricultura e Pecuária, com habilitação para o serviço proposto, mediante contrato de industrialização, e deverá ser previamente autorizada pele equipe técnica da Unidade da Federação onde o estabelecimento estiver registrado."}, {"c": "dou-paragraph", "t": "Art. 63. O importador que tiver sua importação negada com imposição de medida de destruição da mercadoria deverá descrever o procedimento de destruição a ser adotado e apresentá-lo à análise do Auditor Fiscal Federal Agropecuário responsável pelo processo de importação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O Auditor Fiscal Federal Agropecuário responsável pelo processo de importação poderá solicitar manifestação do setor técnico da Secretaria de Defesa Agropecuária, para fins de autorização prévia da destruição."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Da exportação de fertilizantes e correlatos"}, {"c": "dou-paragraph", "t": "Art. 64. A exportação de fertilizantes, corretivos, inoculantes, biofertilizantes, remineralizadores e substratos para plantas dar-se-á por tratamento administrativo de monitoramento, ou seu equivalente, sem imposição de exigência, restrição ou condição no Portal Único de Comércio Exterior, sem prejuízo da utilização posterior dos dados pelo Ministério da Agricultura e Pecuária para o exercício de suas competências e adoção de medidas previstas na legislação em caso de irregularidades."}, {"c": "dou-paragraph", "t": "Art. 65. No caso de reexportação ou devolução de mercadoria nacionalizada, o interessado deverá comprovar o reembarque da mercadoria junto à fiscalização do ponto de egresso da mercadoria, formalizando processo de exportação."}, {"c": "dou-paragraph", "t": "CAPÍTULO IV"}, {"c": "dou-paragraph", "t": "DA IMPORTAÇÃO E DA EXPORTAÇÃO DE SEMENTES, DE MUDAS E DE MATERIAL DE PROPAGAÇÃO VEGETATIVA"}, {"c": "dou-paragraph", "t": "Art. 66. As disposições deste Capítulo aplicam-se a toda importação e exportação de sementes, de mudas e de material de propagação vegetativa, excetuadas as importações e exportações para fins de pesquisa e de experimentação."}, {"c": "dou-paragraph", "t": "Parágrafo único. O disposto no caput inclui as importações para fins de ensaios de Valor de Cultivo e Uso - VCU e de ensaios de adaptação, os quais não são considerados atividades de pesquisa ou de experimentação."}, {"c": "dou-paragraph", "t": "Art. 67. Os produtores, os reembaladores e os comerciantes inscritos no Registro Nacional de Sementes e Mudas - Renasem estão habilitados para importar e exportar sementes, mudas e material de propagação vegetativa, de espécies do grupo para o qual estão inscritos."}, {"c": "dou-paragraph", "t": "Parágrafo único. O material de propagação vegetativa importado por comerciante somente poderá ser comercializado para produtor ou comerciante de mudas inscrito no Renasem."}, {"c": "dou-paragraph", "t": "Art. 68. É permitido ao usuário importar sementes e mudas para uso próprio em área de sua propriedade ou de que tenha a posse."}, {"c": "dou-paragraph", "t": "Art. 69. Somente poderão ser importadas e exportadas sementes, mudas e material de propagação vegetativa de cultivar inscrita no Registro Nacional de Cultivares - RNC ou, quando for o caso, de espécie inscrita no RNC, exceto no caso de importação de cultivar:"}, {"c": "dou-paragraph", "t": "I - para realização de ensaios de VCU e de ensaios de adaptação; ou"}, {"c": "dou-paragraph", "t": "II - com o objetivo exclusivo de reexportação."}, {"c": "dou-paragraph", "t": "Seção I"}, {"c": "dou-paragraph", "t": "Da autorização para importação de sementes, de mudas e de material de propagação vegetativa"}, {"c": "dou-paragraph", "t": "Art. 70. Para a importação de sementes, de mudas e de material de propagação vegetativa exigir-se-á a autorização do Ministério da Agricultura e Pecuária, a qual deverá ser solicitada pelo registro do LPCO contendo as seguintes informações:"}, {"c": "dou-paragraph", "t": "I - nome ou razão social do importador;"}, {"c": "dou-paragraph", "t": "II - CPF ou CNPJ do importador;"}, {"c": "dou-paragraph", "t": "III - número de inscrição do importador no Renasem, exceto no caso de importação para uso próprio;"}, {"c": "dou-paragraph", "t": "IV - finalidade da importação, podendo ser produção de sementes ou de mudas, comercialização, reembalagem, reexportação, ensaio de VCU ou de adaptação ou utilização;"}, {"c": "dou-paragraph", "t": "V - país de origem;"}, {"c": "dou-paragraph", "t": "VI - Nomenclatura Comum Mercosul - NCM;"}, {"c": "dou-paragraph", "t": "VII - nome científico da espécie;"}, {"c": "dou-paragraph", "t": "VIII - denominação da cultivar;"}, {"c": "dou-paragraph", "t": "IX - número de inscrição da cultivar no RNC, exceto nos casos de importação para ensaio de VCU ou ensaio de adaptação ou de importação com objetivo exclusivo de reexportação;"}, {"c": "dou-paragraph", "t": "X - se a cultivar é híbrida ou não;"}, {"c": "dou-paragraph", "t": "XI - categoria do material de propagação, exceto no caso de importação para ensaio de VCU ou de ensaio de adaptação;"}, {"c": "dou-paragraph", "t": "XII - acordo de equivalência de categorias que ampara a importação, quando for o caso;"}, {"c": "dou-paragraph", "t": "XIII - se o material de propagação é organismo geneticamente modificado - OGM ou não;"}, {"c": "dou-paragraph", "t": "XIV - evento OGM, quando for o caso; e"}, {"c": "dou-paragraph", "t": "XV - quantidade e peso líquido."}, {"c": "dou-paragraph", "t": "Art. 71. Deverão ser anexados ao LPCO de autorização para importação:"}, {"c": "dou-paragraph", "t": "I - no caso de importação para realização de ensaios de VCU e de ensaios de adaptação, justificativa técnica contendo:"}, {"c": "dou-paragraph", "t": "a) as seguintes informações do responsável pelos ensaios:"}, {"c": "dou-paragraph", "t": "1. nome;"}, {"c": "dou-paragraph", "t": "2. CPF ou CNPJ;"}, {"c": "dou-paragraph", "t": "3. endereço completo;"}, {"c": "dou-paragraph", "t": "4. telefone; e"}, {"c": "dou-paragraph", "t": "5. correio eletrônico (e-mail);"}, {"c": "dou-paragraph", "t": "b) demonstração da compatibilidade entre a quantidade importada e a necessidade para a aplicação (quantidade de sementes por unidade de peso, número de ensaios, número de repetições, tamanho da parcela e densidade de plantio);"}, {"c": "dou-paragraph", "t": "c) local onde o material ficará armazenado até a instalação dos ensaios;"}, {"c": "dou-paragraph", "t": "d) locais de instalação dos ensaios, com endereço completo e coordenadas geográficas; e"}, {"c": "dou-paragraph", "t": "e) datas prováveis de instalação dos ensaios;"}, {"c": "dou-paragraph", "t": "II - no caso de importação de cultivar não inscrita no RNC, com objetivo exclusivo de multiplicação para reexportação, projeto técnico contendo:"}, {"c": "dou-paragraph", "t": "a) as seguintes informações do responsável pela multiplicação:"}, {"c": "dou-paragraph", "t": "1. nome;"}, {"c": "dou-paragraph", "t": "2. CPF ou CNPJ;"}, {"c": "dou-paragraph", "t": "3. número de inscrição no Renasem;"}, {"c": "dou-paragraph", "t": "4. endereço completo;"}, {"c": "dou-paragraph", "t": "5. telefone; e"}, {"c": "dou-paragraph", "t": "6. correio eletrônico (e-mail);"}, {"c": "dou-paragraph", "t": "b) local onde o material ficará armazenado até o plantio;"}, {"c": "dou-paragraph", "t": "c) datas prováveis de plantio e de colheita e estimativa de produção;"}, {"c": "dou-paragraph", "t": "d) descritores da cultivar a ser produzida e, no caso de híbridos, dos seus progenitores;"}, {"c": "dou-paragraph", "t": "e) autorização do detentor dos direitos da propriedade intelectual da cultivar, no caso de cultivar protegida no Brasil; e"}, {"c": "dou-paragraph", "t": "f) país ou países destinatários da produção;"}, {"c": "dou-paragraph", "t": "III - no caso de importação para uso próprio, relação da(s) propriedade(s) onde as sementes ou as mudas serão utilizadas contendo:"}, {"c": "dou-paragraph", "t": "a) nome;"}, {"c": "dou-paragraph", "t": "b) endereço completo;"}, {"c": "dou-paragraph", "t": "c) coordenadas geográficas; e"}, {"c": "dou-paragraph", "t": "d) área a ser plantada; e"}, {"c": "dou-paragraph", "t": "IV - no caso de importação mediante quarentena vegetal, Permissão de Importação emitida pelo Departamento de Sanidade Vegetal e Insumos Agrícolas - DSV."}, {"c": "dou-paragraph", "t": "Art. 72. A autorização para importação terá validade de:"}, {"c": "dou-paragraph", "t": "I - cento e oitenta dias, quando concedida para uma única operação; e"}, {"c": "dou-paragraph", "t": "II - trezentos e sessenta e cinco dias, quando concedida para múltiplas operações."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os prazos previstos nos incisos I e II estão condicionados à validade da inscrição do importador no Renasem e da inscrição da cultivar no RNC."}, {"c": "dou-paragraph", "t": "Seção II"}, {"c": "dou-paragraph", "t": "Do controle agropecuário na importação de sementes, de mudas e de material de propagação vegetativa"}, {"c": "dou-paragraph", "t": "Art. 73. O controle agropecuário no momento da importação, para fins de liberação agropecuária, deverá ser solicitado após o deferimento do LPCO, pelo registro da Duimp contendo as seguintes informações:"}, {"c": "dou-paragraph", "t": "I - país de procedência;"}, {"c": "dou-paragraph", "t": "II - via de transporte;"}, {"c": "dou-paragraph", "t": "III - ponto de ingresso;"}, {"c": "dou-paragraph", "t": "VI - unidade de despacho;"}, {"c": "dou-paragraph", "t": "V - local de destino;"}, {"c": "dou-paragraph", "t": "VI - local onde o material ficará depositado, quando for ocaso; e"}, {"c": "dou-paragraph", "t": "VII - laboratório de diagnóstico fitossanitário, quando for o caso."}, {"c": "dou-paragraph", "t": "Art. 74. Deverão ser anexados à Duimp:"}, {"c": "dou-paragraph", "t": "I - fatura comercial;"}, {"c": "dou-paragraph", "t": "II - boletim de análise de sementes, de mudas ou de material de propagação vegetativa, conforme o caso, ou documento equivalente, emitido no país de origem ou de procedência, contendo os atributos previstos nos padrões brasileiros de identidade e qualidade, obedecidas as metodologias e os procedimentos de análise reconhecidos pelo Ministério da Agricultura e Pecuária;"}, {"c": "dou-paragraph", "t": "III - Certificado Fitossanitário ou Certificado Fitossanitário de Reexportação original, emitido pela Organização Nacional de Proteção Fitossanitária - ONPF do país exportador ou reexportador, quando for o caso, atestando que a partida cumpre os requisitos fitossanitários indicados;"}, {"c": "dou-paragraph", "t": "IV - termo de depositário, no caso de liberação antecipada; e"}, {"c": "dou-paragraph", "t": "V - cópia do romaneio de carga ou packing list."}, {"c": "dou-paragraph", "t": "§ 1º No caso de mudas ou de material de propagação vegetativa, o documento de que trata o inciso II não será exigido quando não houver padrão estabelecido para a espécie ou quando o padrão não tiver atributo cuja determinação dependa de análise laboratorial."}, {"c": "dou-paragraph", "t": "§ 2º No caso de sementes, de mudas ou de material de propagação vegetativa importado para fins de ensaios de VCU ou ensaios de adaptação, o documento de que trata o inciso II não será exigido."}, {"c": "dou-paragraph", "t": "Art. 75. As sementes, as mudas e o material de propagação vegetativa importados estão sujeitos à coleta de amostra para análise fiscal dos atributos de identidade e qualidade, realizada em laboratório oficial, e para análise fitossanitária, realizada em laboratório oficial ou credenciado pelo Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 76. A coleta de amostra para análise fitossanitária, quando exigida, ocorrerá no local de despacho de importação perante o Ministério da Agricultura e Pecuária, conforme definição do órgão técnico central de sanidade vegetal."}, {"c": "dou-paragraph", "t": "Art. 77. A entrega antecipada da mercadoria poderá ser autorizada quando a liberação agropecuária depender do resultado da análise fitossanitária."}, {"c": "dou-paragraph", "t": "Parágrafo único. Na hipótese prevista no caput a liberação agropecuária ocorrerá somente se o laudo do diagnóstico fitossanitário atestar a ausência de pragas regulamentadas."}, {"c": "dou-paragraph", "t": "Art. 78. A coleta de amostra para análise fiscal dos atributos de identidade e qualidade, ocorrerá no local de despacho de importação perante o Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 79. A semente, a muda ou o material de propagação vegetativa importado poderá ser dispensado da coleta de amostra para análise fiscal dos atributos de identidade e qualidade previstos nos padrões da espécie, sem prejuízo da legislação fitossanitária, quando:"}, {"c": "dou-paragraph", "t": "I - esta dispensa estiver prevista em acordos e tratados internacionais;"}, {"c": "dou-paragraph", "t": "II - estiver acompanhada de boletim de análise de sementes, representativo do lote importado, emitido por laboratório que utiliza metodologia da International Seed Testing Association - ISTA ou da Association of Official Seed Analysts - AOSA;"}, {"c": "dou-paragraph", "t": "III - se tratar de espécies para as quais os métodos e procedimentos de análise não estejam oficializados pelo Ministério da Agricultura e Pecuária;"}, {"c": "dou-paragraph", "t": "IV - não houver padrão estabelecido para a espécie; ou"}, {"c": "dou-paragraph", "t": "V - quando a importação se der para fins de ensaios de VCU ou ensaios de adaptação ou de reexportação."}, {"c": "dou-paragraph", "t": "Parágrafo único. A critério do Ministério da Agricultura e Pecuária, poderá ser determinada coleta de amostras para fins de monitoramento, de controle, por motivos de suspeita ou resultante de quaisquer ações necessárias para salvaguardar a agropecuária brasileira."}, {"c": "dou-paragraph", "t": "Art. 80. Havendo coleta de amostra para análise fiscal dos atributos de identidade e qualidade, cópia do boletim oficial de análise será disponibilizada ao importador no prazo de trinta dias, contado da data de emissão do boletim."}, {"c": "dou-paragraph", "t": "Parágrafo único. Quando o lote de sementes, de mudas ou de material de propagação vegetativa importado não atender aos padrões, o boletim de análise oficial será acompanhado de parecer da fiscalização."}, {"c": "dou-paragraph", "t": "Art. 81. O lote de sementes, de mudas ou de material de propagação vegetativa, ou parte dele, que não atenda às normas e aos padrões oficiais, ouvido o importador e a critério do Ministério da Agricultura e Pecuária, deverá ser devolvido, reexportado, destruído ou utilizado para outro fim, com exceção da propagação, com a supervisão do Ministério da Agricultura e Pecuária de qualquer ação decorrente."}, {"c": "dou-paragraph", "t": "Art. 82. O importador será responsável pela garantia dos atributos de identidade e qualidade do lote importado."}, {"c": "dou-paragraph", "t": "Parágrafo único. Havendo coleta de amostra para análise fiscal dos atributos de identidade e qualidade, o importador poderá comercializar ou utilizar o lote antes mesmo do resultado da análise, sem prejuízo do previsto na legislação fitossanitária, mas estará sujeito às penalidades cabíveis quando o lote não atender aos padrões estabelecidos pelo Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 83. O importador deverá providenciar a emissão do Certificado de Sementes Importadas, do Termo de Conformidade de Sementes Importadas, do Certificado de Mudas Importadas, do Termo de Conformidade de Mudas Importadas, do Certificado de Material de Propagação Importado e do Termo de Conformidade de Material de Propagação Importado, conforme o caso."}, {"c": "dou-paragraph", "t": "§ 1º Os documentos de que trata o caput deverão ser emitidos com base:"}, {"c": "dou-paragraph", "t": "I - no boletim de análise de sementes, de mudas ou de material de propagação vegetativa emitido no país de origem ou de procedência;"}, {"c": "dou-paragraph", "t": "II - no boletim oficial de análise de sementes, de mudas ou de material de propagação vegetativa; ou"}, {"c": "dou-paragraph", "t": "III - no boletim de análise de sementes, de mudas ou de material de propagação vegetativa emitido por laboratório credenciado no Renasem."}, {"c": "dou-paragraph", "t": "§ 2º O disposto no § 1º não se aplica no caso de mudas ou de material de propagação vegetativa quando não houver padrão estabelecido para a espécie ou quando o padrão não tiver atributo cuja determinação dependa de análise laboratorial."}, {"c": "dou-paragraph", "t": "§ 3º Para comercialização das sementes importadas no território nacional, o Termo de Conformidade de Sementes Importadas poderá constar na embalagem com os seguintes dizeres: \"Atesto que este lote de sementes importadas atende às normas nacionais vigentes, Responsável Técnico RENASEM n.º [nº do RENASEM do RT]\"."}, {"c": "dou-paragraph", "t": "§ 4º Na hipótese prevista no § 3º, o Termo de Conformidade de Sementes Importadas ainda deverá ser emitido nos termos da Portaria MAPA nº 538, de 20 de dezembro de 2022, e mantido à disposição da fiscalização no importador e sua cópia deverá ser disponibilizada ao adquirente quando solicitada."}, {"c": "dou-paragraph", "t": "Art. 84. A interrupção do processo de produção de sementes ou de mudas para reexportação, em qualquer de suas etapas, ou a impossibilidade de exportação do material produzido deverá ser informada ao Ministério da Agricultura e Pecuária, que decidirá, quando for o caso, sua destinação, mediante requerimento do importador."}, {"c": "dou-paragraph", "t": "Seção III"}, {"c": "dou-paragraph", "t": "Da exportação de sementes, de mudas e de material de propagação vegetativa"}, {"c": "dou-paragraph", "t": "Art. 85. A exportação de sementes, de mudas e de material de propagação vegetativa deverá ser comunicada pelo módulo LPCO, ou seu equivalente, do Portal Único de Comércio Exterior"}, {"c": "dou-paragraph", "t": "Art. 86. O LPCO de comunicado de exportação deverá ser registrado conforme modelo específico, contendo as seguintes informações:"}, {"c": "dou-paragraph", "t": "I - nome ou razão social do exportador;"}, {"c": "dou-paragraph", "t": "II - CPF ou CNPJ do exportador;"}, {"c": "dou-paragraph", "t": "III - número de inscrição do exportador no Renasem;"}, {"c": "dou-paragraph", "t": "IV - CPF ou CNPJ do produtor ou reembalador do material de propagação;"}, {"c": "dou-paragraph", "t": "V - número de inscrição do produtor ou reembalador do material de propagação no Renasem;"}, {"c": "dou-paragraph", "t": "VI - safra;"}, {"c": "dou-paragraph", "t": "VII - Nomenclatura Comum Mercosul - NCM;"}, {"c": "dou-paragraph", "t": "VIII - nome científico da espécie;"}, {"c": "dou-paragraph", "t": "IX - denominação da cultivar;"}, {"c": "dou-paragraph", "t": "X - número de inscrição da cultivar no RNC, exceto no caso de cultivar não inscrita no RNC, importada com objetivo exclusivo de reexportação;"}, {"c": "dou-paragraph", "t": "XI - identificação do lote;"}, {"c": "dou-paragraph", "t": "XII - categoria do material de propagação, exceto no caso de exportação de sementes brutas;"}, {"c": "dou-paragraph", "t": "XIII - tipo de embalagem e quantidade de embalagens;"}, {"c": "dou-paragraph", "t": "XIV - quantidade e peso líquido do material de propagação;"}, {"c": "dou-paragraph", "t": "XV - tipo de operação: exportação ou reexportação; e"}, {"c": "dou-paragraph", "t": "XVI - número da Duimp, no caso de reexportação."}, {"c": "dou-paragraph", "t": "Art. 87. Deverão ser anexados ao LPCO de comunicado de exportação:"}, {"c": "dou-paragraph", "t": "I - Atestado de Origem Genética, Certificado de Sementes, Termos de Conformidade de Sementes, Certificado de Mudas, Termos de Conformidade de Mudas, Certificado de Material de Propagação, Termos de Conformidade de Material de Propagação, conforme o caso, e termos aditivos, se houver, exceto no caso de exportação de sementes brutas;"}, {"c": "dou-paragraph", "t": "II - comprovante de inscrição do(s) campo(s) no Ministério da Agricultura e Pecuária, com status \"Aprovado\", no caso de exportação de sementes brutas;"}, {"c": "dou-paragraph", "t": "III - autorização para transferência de produção bruta, quando for o caso;"}, {"c": "dou-paragraph", "t": "IV - autorização do detentor do direito de proteção da cultivar, exceto nos casos de:"}, {"c": "dou-paragraph", "t": "a) reexportação sem multiplicação; ou"}, {"c": "dou-paragraph", "t": "b) certificação pelas regras da Organização para a Cooperação e Desenvolvimento Econômico - OCDE ou da Association of Official Seed Certifying Agencies - AOSCA;"}, {"c": "dou-paragraph", "t": "V - documentação exigida pela legislação ambiental, quando for o caso;"}, {"c": "dou-paragraph", "t": "VI - autorização do órgão técnico de fiscalização de agrotóxicos, no caso de uso de agrotóxico em tratamento de semente ou de muda de cultura diversa às recomendadas em rótulo e bula, quando for o caso;"}, {"c": "dou-paragraph", "t": "VII - documento comprobatório das exigências fitossanitárias do país importador (import permit), quando couber;"}, {"c": "dou-paragraph", "t": "VIII - cópia da fatura comercial ou da nota fiscal;"}, {"c": "dou-paragraph", "t": "XI - cópia do romaneio de carga ou packing list; e"}, {"c": "dou-paragraph", "t": "XIII - relatório descritivo das operações que tenham alterado as características das sementes, das mudas ou do material de propagação vegetativa importado com o objetivo exclusivo de reexportação, no caso de cultivar não inscrita no RNC, indicando as alterações, bem como a quantidade e o destino do descarte, quando for o caso."}, {"c": "dou-paragraph", "t": "Art. 88. O exportador será responsável pelas informações fornecidas e pelos documentos anexados ao LPCO, podendo responder por eventuais irregularidades constatadas pela fiscalização durante ou após a exportação."}, {"c": "dou-paragraph", "t": "CAPÍTULO V"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES TRANSITÓRIAS"}, {"c": "dou-paragraph", "t": "Art. 89. O tratamento administrativo dos processos protocolados e ainda não concluídos até a data de entrada em vigor desta Portaria seguirá o disposto no art. 43 da Portaria MAPA nº 835, de 9 de setembro de 2025."}, {"c": "dou-paragraph", "t": "Art. 90. O Registro de Pessoa Jurídica como Importador e Exportador de produtos técnicos, pré-misturas, agrotóxicos formulados e afins emitido pelos órgãos competentes dos Estados ou do Distrito Federal será aceito para o cumprimento do art. 15 até a disponibilização pelo Ministério da Agricultura e Pecuária do sistema eletrônico de registro de pessoas jurídicas."}, {"c": "dou-paragraph", "t": "CAPÍTULO VI"}, {"c": "dou-paragraph", "t": "DISPOSIÇÕES FINAIS"}, {"c": "dou-paragraph", "t": "Art. 91. Os importadores e os exportadores deverão manter arquivados, pelo prazo mínimo de cinco anos, os documentos comprobatórios das operações, os quais deverão ser apresentados à autoridade competente quando solicitados."}, {"c": "dou-paragraph", "t": "Art. 92. A autoridade fiscal poderá solicitar a apresentação de originais de documentos digitalizados apresentados por meio do Portal Único de Comércio Exterior ou seu equivalente, quando houver suspeita quanto à autenticidade, autoria ou integridade."}, {"c": "dou-paragraph", "t": "Art. 93. Os casos omissos e as dúvidas suscitadas na execução desta Portaria serão resolvidos pelo Departamento de Sanidade Vegetal e Insumos Agrícolas do Ministério da Agricultura e Pecuária."}, {"c": "dou-paragraph", "t": "Art. 94. Ficam revogadas:"}, {"c": "dou-paragraph", "t": "I - a Instrução Normativa MAPA nº 25, de 27 de junho de 2017;"}, {"c": "dou-paragraph", "t": "II - a Instrução Normativa SARC nº 14, de 16 de outubro de 2003;"}, {"c": "dou-paragraph", "t": "III - a Instrução Normativa SARC nº 8, de 02 de julho de 2003; e"}, {"c": "dou-paragraph", "t": "IV - a Instrução Normativa SDA/MAPA nº 26, de 20 de julho de 2017."}, {"c": "dou-paragraph", "t": "Art. 95. Esta Portaria entrame em vigor em XX."}, {"c": "anexo", "t": "Anexo ITERMO DE COMPROMISSO - CONSUMIDOR FINAL - PRODUTOR RURAL OU EMPRESA AGRÍCOLA"}, {"c": "dou-paragraph", "t": "Nome/Razão Social:"}, {"c": "dou-paragraph", "t": "Endereço:"}, {"c": "dou-paragraph", "t": "CPF/CNPJ Nº:"}, {"c": "dou-paragraph", "t": "Pretendendo importar o produto (especificação e quantidade):"}, {"c": "dou-paragraph", "t": "__________________________________________________________________"}, {"c": "dou-paragraph", "t": "Pelo presente termo, comprometo-me a utilizar o insumo exclusivamente de acordo com as informações prestadas. Comprometo-me ainda a não ceder, repassar ou revender este insumo para terceiros."}, {"c": "dou-paragraph", "t": "Por ser a expressão da verdade, firmo o presente TERMO DE COMPROMISSSO."}, {"c": "dou-paragraph", "t": "Local e Data ________________________________"}, {"c": "dou-paragraph", "t": "Identificação e assinatura do Importador"}, {"c": "anexo", "t": "Anexo IITERMO DE COMPROMISSO - CONSUMIDOR FINAL - COOPERATIVAS AGROPECUÁRIAS"}, {"c": "dou-paragraph", "t": "Cooperativa:"}, {"c": "dou-paragraph", "t": "Endereço:"}, {"c": "dou-paragraph", "t": "CPF/CNPJ Nº:"}, {"c": "dou-paragraph", "t": "Pretendendo importar o produto (especificação e quantidade):"}, {"c": "dou-paragraph", "t": "__________________________________________________________________"}, {"c": "dou-paragraph", "t": "Pelo presente termo, compromete-se a utilizar o insumo exclusivamente de acordo com as informações prestadas. Compromete-se ainda a não ceder, repassar ou revender este insumo para terceiros não cooperados."}, {"c": "dou-paragraph", "t": "Por ser a expressão da verdade, firmo o presente TERMO DE COMPROMISSSO."}, {"c": "dou-paragraph", "t": "Local e Data ____________________________________"}, {"c": "dou-paragraph", "t": "Identificação e assinatura do Importador"}, {"c": "anexo", "t": "Anexo IIITERMO DE COMPROMISSO - AMOSTRA PARA FINS DE PESQUISA E EXPERIMENTAÇÃO"}, {"c": "dou-paragraph", "t": "Razão Social:"}, {"c": "dou-paragraph", "t": "Endereço:"}, {"c": "dou-paragraph", "t": "CNPJ Nº:"}, {"c": "dou-paragraph", "t": "Pretendendo importar o produto (especificação e quantidade):"}, {"c": "dou-paragraph", "t": "__________________________________________________________________"}, {"c": "dou-paragraph", "t": "Pelo presente termo, compromete-se a utilizar o insumo exclusivamente de acordo com as informações prestadas. Compromete-se ainda a não ceder, repassar ou revender este insumo para terceiros e providenciar a destruição ou devolução à origem de qualquer sobra do material."}, {"c": "dou-paragraph", "t": "Por ser a expressão da verdade, firmo o presente TERMO DE COMPROMISSSO."}, {"c": "dou-paragraph", "t": "Local e Data ____________________________________"}, {"c": "dou-paragraph", "t": "Identificação e assinatura do Importado"}, {"c": "anexo", "t": "Anexo IV TERMO DE COMPROMISSO - AMOSTRA PARA FINS DE ANÁLISE LABORATORIAL"}, {"c": "dou-paragraph", "t": "Razão Social:"}, {"c": "dou-paragraph", "t": "Endereço:"}, {"c": "dou-paragraph", "t": "CNPJ Nº:"}, {"c": "dou-paragraph", "t": "Pretendendo importar o produto (especificação e quantidade):"}, {"c": "dou-paragraph", "t": "__________________________________________________________________"}, {"c": "dou-paragraph", "t": "Pelo presente termo, compromete-se a utilizar o insumo exclusivamente de acordo com as informações prestadas. Compromete-se ainda a não ceder, repassar ou revender este insumo para terceiros e providenciar a destruição ou devolução à origem de qualquer sobra do material."}, {"c": "dou-paragraph", "t": "Por ser a expressão da verdade, firmo o presente TERMO DE COMPROMISSSO."}, {"c": "dou-paragraph", "t": "Local e Data _____"}, {"c": "dou-paragraph", "t": "Identificação e assinatura do Importador"}]});